#include "editor.hpp"
namespace touch::ui {
void Editor::settings_panel(){ImGui::TextColored(ImGui::ColorConvertU32ToFloat4(theme::select),"Settings");ImGui::TextUnformatted("Video (applies on next Run)");const char* resolutions[]={"480p","720p","1080p"};int widths[]={854,1280,1920},heights[]={480,720,1080};for(int i=0;i<3;++i){if(i)ImGui::SameLine();if(ImGui::Button(resolutions[i])){document.edit([&](Graph& g){g.width=widths[i];g.height=heights[i];});changed();}}for(int fps:{24,30,60}){if(fps!=24)ImGui::SameLine();if(ImGui::Button((std::to_string(fps)+" FPS").c_str())){document.edit([&](Graph& g){g.fps=fps;});changed();}}if(ImGui::SliderFloat("Volume dB",&volume_db,-60,12))services.runtime.volume(volume_db);ImGui::Checkbox("Grid",&grid);ImGui::Combo("Transparency",&background,"Dark\0Light\0Checkerboard\0");ImGui::Separator();ImGui::TextUnformatted("Plugins");if(ImGui::Button("Load plugin"))file_dialog(3);if(ImGui::Button("Stop and unload plugins")){services.runtime.run(false);services.plugins.unload_all(false);status="Plugins unloaded; node data preserved";}}
}
